(function(E){ const x = E["int-m2"] = E["int-m2"] || {units:{}}; x.units["int-4"] = {"grammar":{"id":"c-int-4-g","level":"B1","course":"interview","unit":"int-4","title":"Good at planning: -ing after a preposition","titleTr":"Good at planning: edattan sonra -ing","titleFa":"فعل با ing بعد از حرف اضافه (good at planning)","formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["good at + -ing","I'm good at planning projects."],["responsible for + -ing","I'm responsible for training new staff."],["interested in + -ing","I'm interested in learning new software."],["before / after / without + -ing","I never send a report without checking it."]]},"wrong":"I'm good at solve problems quickly.","right":"I'm good at solving problems quickly.","blank":{"sentence":"I am responsible for ___ the night team every Monday.","word":"training","distractors":["train","to train"]},"wrong2":"I always check the order before send it.","right2":"I always check the order before sending it.","blank2":{"sentence":"I'm really good at ___ angry customers down.","word":"calming","distractors":["calm","to calm"]},"expParts":{"rule":[{"en":"A preposition needs a noun after it, so the verb takes -ing.","tr":"Edattan sonra isim gelir; bu yüzden fiil -ing alır.","fa":"بعد از حرف اضافه باید اسم بیاید؛ برای همین فعل ‎-ing می‌گیرد.","ex":"I'm good at planning projects."},{"en":"Common pairs: good at, responsible for, interested in.","tr":"Sık kullanılanlar: good at, responsible for, interested in.","fa":"جفت‌های رایج: good at، responsible for، interested in.","ex":"I'm interested in learning new systems."},{"en":"before, after and without are prepositions too, so they also take -ing.","tr":"before, after ve without da edattır; bu yüzden onlardan sonra da -ing gelir.","fa":"before، after و without هم حرف اضافه‌اند؛ پس بعد از آن‌ها هم ‎-ing می‌آید.","ex":"I never send a report without checking it."}],"test":{"en":"Is the word just before the verb at, in, for, of, about, before, after or without? Add -ing.","tr":"Fiilden hemen önceki kelime at, in, for, of, about, before, after ya da without mı? -ing ekle.","fa":"کلمه‌ای که درست قبل از فعل آمده at، in، for، of، about، before، after یا without است؟ ‎-ing اضافه کن."},"contrast":{"en":"Turkish adds a case ending to the verb ('planlamakta iyiyim') and Persian uses a noun ('در برنامه‌ریزی خوبم'), so learners reach for the base verb: 'good at plan'. English needs -ing.","tr":"Türkçede fiile bir ek gelir ('planlamakta iyiyim'). İngilizcede edattan sonra fiil -ing alır: good at planning.","fa":"در فارسی بعد از حرف اضافه اسم یا مصدر می‌آید («در برنامه‌ریزی خوبم»). در انگلیسی بعد از حرف اضافه فعل ‎-ing می‌گیرد: good at planning."}},"errorWatch":[{"find":["good at plan","good at solve","good at manage","good at speak","good at organise","good at organize","good at calm","good at make","good at find","good at sell","responsible for train","responsible for manage","responsible for check","responsible for plan","interested in learn"],"fix":{"en":"After a preposition the verb takes -ing: 'I'm good at planning', 'responsible for training'.","tr":"Edattan sonra fiil -ing alır: 'I'm good at planning', 'responsible for training'.","fa":"بعد از حرف اضافه فعل ‎-ing می‌گیرد: «I'm good at planning»، «responsible for training»."}},{"find":["before send","before start","before leave","after finish","without ask","without check","without say"],"fix":{"en":"before, after and without take -ing: 'before sending it', 'without asking'.","tr":"before, after ve without -ing alır: 'before sending it', 'without asking'.","fa":"before، after و without با ‎-ing می‌آیند: «before sending it»، «without asking»."}}]},"b2":{"id":"c-int-4-b2","level":"B2","track":"B2","course":"interview","unit":"int-4","title":"Changing a habit: used to, be used to, get used to","titleTr":"Bir alışkanlığı değiştirmek: used to, be used to, get used to","titleFa":"عوض کردن یک عادت: used to، be used to، get used to","formsTable":{"headers":{"en":["Form","Example"],"tr":["Yapı","Örnek"],"fa":["ساختار","مثال"]},"rows":[["used to + verb: a past habit, stopped","I used to say yes to every task."],["be used to + -ing: normal for me now","I'm used to working nights."],["get used to + -ing: becoming normal","I'm getting used to saying no politely."]]},"wrong":"I'm used to work under pressure.","right":"I'm used to working under pressure.","blank":{"sentence":"I ___ answer every email at midnight, but now I switch off at eight.","word":"used to","distractors":["am used to","get used to"]},"wrong2":"I am getting used to ask for help.","right2":"I am getting used to asking for help.","blank2":{"sentence":"After a year of night shifts, I'm used to ___ at 4 a.m.","word":"waking up","distractors":["wake up","woke up"]},"useIn":{"en":"B2: in your weakness answer, show the change with used to, or with be / get used to + -ing.","tr":"B2: zayıf yön cevabında değişimi used to ile ya da be / get used to + -ing ile göster.","fa":"در مسیر B2: در جواب نقطه‌ی ضعفت، تغییر را با used to نشان بده، یا با be used to و get used to و فعل با ing."},"exitItem":{"from":"int-4","kind":"blank","prompt":"She is slowly getting used to ___ English at work every day.","options":["speaking","speak","spoke"],"correct":0},"expParts":{"rule":[{"en":"used to + verb: a past habit that stopped.","tr":"used to + fiil: bitmiş geçmiş bir alışkanlık.","fa":"با used to و فعل ساده از عادتی می‌گویی که در گذشته داشتی و تمام شده است.","ex":"I used to say yes to every task."},{"en":"be used to + -ing: normal for me now.","tr":"be used to + -ing: artık benim için normal.","fa":"با be used to و فعل با ing می‌گویی چیزی حالا برایت عادی است.","ex":"I'm used to working nights."},{"en":"get used to + -ing: becoming normal.","tr":"get used to + -ing: normal hâle geliyor.","fa":"با get used to و فعل با ing می‌گویی چیزی دارد برایت عادی می‌شود.","ex":"I'm getting used to saying no politely."}],"test":{"en":"Is there am, is, are or get before 'used to'? Then -ing. No be or get? Then the base verb.","tr":"'used to'dan önce am, is, are ya da get var mı? O zaman -ing. be ya da get yok mu? O zaman yalın fiil.","fa":"قبل از used to یکی از am، is، are یا get هست؟ پس ‎-ing. نه be هست نه get؟ پس شکل ساده‌ی فعل."},"contrast":{"en":"Turkish 'eskiden yapardım' and 'yapmaya alıştım', like Persian 'قبلاً ... می‌کردم' and 'عادت کرده‌ام', are different forms. English uses 'used to' for both, so the verb after it decides the meaning.","tr":"Türkçede 'eskiden yapardım' ve 'yapmaya alıştım' farklı yapılardır. İngilizce ikisi için de 'used to' kullanır; anlamı ondan sonraki fiilin biçimi belirler.","fa":"در فارسی «قبلاً ... می‌کردم» و «به ... عادت کرده‌ام» دو ساختار جدا هستند. انگلیسی برای هر دو used to دارد و شکل فعلِ بعدش معنی را مشخص می‌کند."}},"errorWatch":[{"find":["i'm used to work","i am used to work","getting used to ask","get used to ask","i'm used to speak","i am used to speak","i'm used to wake","am used to wake","got used to work","getting used to work"],"fix":{"en":"After be used to / get used to, use -ing: 'I'm used to working under pressure.'","tr":"be used to / get used to'dan sonra -ing kullan: 'I'm used to working under pressure.'","fa":"بعد از be used to / get used to از ‎-ing استفاده کن: «I'm used to working under pressure.‎»"}}]},"vocab":{"id":"c-int-4-v","level":"B1","category":"vocab","course":"interview","unit":"int-4","goals":["career"],"title":{"en":"Strengths and Weaknesses","tr":"Güçlü ve Zayıf Yönler","fa":"نقاط قوت و ضعف"},"cards":[{"word":"strength","sentence":"My main strength is staying calm when plans change.","meaning":{"en":"Something you are especially good at.","tr":"güçlü yön.","fa":"نقطه‌ی قوت"}},{"word":"weakness","sentence":"A real weakness with a plan sounds honest.","meaning":{"en":"Something you are not good at yet.","tr":"zayıf yön.","fa":"نقطه‌ی ضعف"}},{"word":"example","sentence":"Can you give me an example of that?","meaning":{"en":"One real case that shows what you mean.","tr":"örnek.","fa":"مثال؛ نمونه"}},{"word":"improve","sentence":"I'm working to improve my spreadsheet skills.","meaning":{"en":"To get better, or to make something better.","tr":"geliştirmek, iyileştirmek.","fa":"بهتر کردن؛ پیشرفت کردن"}},{"word":"feedback","sentence":"My manager's feedback helped me see the problem.","meaning":{"en":"Comments about how well you did something.","tr":"geri bildirim.","fa":"بازخورد"}},{"word":"organised","sentence":"She keeps a very organised calendar.","meaning":{"en":"Planning things well and keeping them in order.","tr":"düzenli, planlı.","fa":"منظم"}},{"word":"deadline","sentence":"I have never missed a project deadline.","meaning":{"en":"The latest time something must be done.","tr":"son teslim tarihi.","fa":"مهلت؛ ضرب‌الاجل"}},{"word":"under pressure","sentence":"I stay calm under pressure, even on busy days.","meaning":{"en":"When there is stress or little time.","tr":"baskı altında.","fa":"تحت فشار"}},{"word":"take a course","sentence":"Last year I took a course in Excel.","meaning":{"en":"To study something in a set of lessons.","tr":"kurs almak, bir kursa katılmak.","fa":"یک دوره‌ی آموزشی گذراندن"},"gap":"took a course","accept":["took a course"]},{"word":"ask for help","sentence":"I've learned to ask for help early.","meaning":{"en":"To ask someone to help you.","tr":"yardım istemek.","fa":"کمک خواستن"}}]},"judge":{"id":"c-int-4-j","course":"interview","unit":"int-4","type":"judge","title":{"en":"Claim, proof, plan","tr":"İddia, kanıt, plan","fa":"ادعا، شاهد، برنامه"},"prompt":"Five answers about strengths and weaknesses, from five different people.","parts":["A specific point","Real proof or a result","Linked to the job, or a plan"],"instruction":{"en":"Tap what each answer has. The strongest answer has all three.","tr":"Her cevapta ne olduğuna dokun. En güçlü cevapta üçü de vardır.","fa":"روی چیزهایی که هر جواب دارد بزن. قوی‌ترین جواب هر سه را دارد."},"items":[{"by":"AI tool","answer":"My greatest strength is my unwavering dedication and my passion for excellence in everything I do.","present":[],"fix":{"en":"Big words and no fact. Name a skill: \"I'm good at finding errors in reports.\" Then prove it.","tr":"Büyük laflar var, gerçek yok. Bir beceri söyle: \"I'm good at finding errors in reports.\" Sonra kanıtla.","fa":"کلمه‌های بزرگ است و هیچ واقعیتی ندارد. یک مهارت بگو: «I'm good at finding errors in reports.» بعد ثابتش کن."}},{"by":"Nurse","answer":"My biggest weakness is that I'm a perfectionist. I care too much.","present":[],"fix":{"en":"Interviewers have heard this many times, and it hides the answer. Choose something real that you are working on.","tr":"Mülakatçılar bunu çok duydu ve bu cevap asıl konuyu saklıyor. Üzerinde çalıştığın gerçek bir şey seç.","fa":"مصاحبه‌کننده‌ها این را بارها شنیده‌اند و جواب اصلی را پنهان می‌کند. چیز واقعی‌ای انتخاب کن که رویش کار می‌کنی."}},{"by":"Accountant","answer":"I'm good at finding errors in reports.","present":["A specific point"],"fix":{"en":"A real skill, but only a claim so far. Add a moment and a result: \"Last year I found an error that saved us 40,000 lira.\"","tr":"Gerçek bir beceri, ama şimdilik sadece iddia. Bir an ve sonuç ekle: \"Last year I found an error that saved us 40,000 lira.\"","fa":"مهارت واقعی است، ولی فعلاً فقط ادعاست. یک موقعیت و نتیجه اضافه کن: «Last year I found an error that saved us 40,000 lira.»"}},{"by":"Software tester","answer":"My weakness is that I don't pay attention to small details, and I often miss mistakes.","present":["A specific point"],"fix":{"en":"Honest, but small details are the heart of testing. Choose a real weakness the job can live with, and add your plan.","tr":"Dürüst, ama küçük ayrıntılar test işinin özü. İşin idare edebileceği gerçek bir zayıf yön seç ve planını ekle.","fa":"صادقانه است، ولی در کار تست جزئیات کوچک اصل کارند. ضعف واقعی‌ای انتخاب کن که برای این شغل مشکلی ایجاد نکند و برنامه‌ات را هم بگو."}},{"by":"Good model","answer":"I used to stay quiet in meetings, and my manager said my ideas got lost. Now I prepare one point before each meeting and say it early. Last month I presented our plan to the whole department.","present":["A specific point","Real proof or a result","Linked to the job, or a plan"],"fix":null}]},"speaking":{"id":"int-4","course":"interview","unit":"int-4","topic":{"en":"Your strength and your weakness","tr":"Güçlü yönün ve zayıf yönün","fa":"نقطه‌ی قوت و نقطه‌ی ضعف تو"},"warmup":{"en":"Finish this sentence three different ways: \"I'm good at...\"","tr":"Bu cümleyi üç farklı şekilde tamamla: \"I'm good at...\"","fa":"این جمله را به سه شکل مختلف تمام کن: «I'm good at...‎»"},"questions":[{"en":"\"What are your strengths?\" Name one skill with \"good at + -ing\".","tr":"\"What are your strengths?\" \"good at + -ing\" ile bir beceri söyle.","fa":"«What are your strengths?‎» یک مهارت را با «good at + ‎-ing» بگو."},{"en":"Give proof: one real moment, with a number or a result.","tr":"Kanıt ver: bir sayı ya da sonuçla birlikte gerçek bir an.","fa":"شاهد بیاور: یک موقعیت واقعی، با یک عدد یا یک نتیجه."},{"en":"\"What is your biggest weakness?\" Choose something real, but not the heart of the job.","tr":"\"What is your biggest weakness?\" Gerçek bir şey seç, ama işin özü olmasın.","fa":"«What is your biggest weakness?‎» چیزی واقعی انتخاب کن، اما نه مهارت اصلی آن کار را."},{"en":"Say what you are doing about it now.","tr":"Şu anda bunun için ne yaptığını söyle.","fa":"بگو الان برایش چه کار می‌کنی."}],"followups":[{"en":"90 seconds, then 60, then 45: the strength with proof, the weakness with its fix.","tr":"90 saniye, sonra 60, sonra 45: kanıtıyla güçlü yön, çözümüyle zayıf yön.","fa":"نقطه‌ی قوت را با شاهدش و نقطه‌ی ضعف را با راه‌حلش بگو: اول در ۹۰ ثانیه، بعد ۶۰ و بعد ۴۵."}],"expressions":[{"phrase":"I'm good at + -ing","meaning":{"en":"Names a skill, not an adjective.","tr":"Bir sıfat değil, bir beceri söyler.","fa":"یک مهارت را می‌گوید، نه یک صفت."}},{"phrase":"For example, last...","meaning":{"en":"Starts your proof.","tr":"Kanıtını sunmaya başlar.","fa":"شاهدت را شروع می‌کند."}},{"phrase":"What I'm doing about it is...","meaning":{"en":"Turns a weakness into a plan.","tr":"Zayıf yönü bir plana dönüştürür.","fa":"نقطه‌ی ضعف را به یک برنامه تبدیل می‌کند."}}],"selfCheck":[{"en":"My strength was a skill, not an adjective (\"good at + -ing\").","tr":"Güçlü yönüm bir sıfat değil, bir beceriydi (\"good at + -ing\").","fa":"نقطه‌ی قوتم یک مهارت بود، نه یک صفت («good at + ‎-ing»)."},{"en":"I gave one real moment as proof, with a result.","tr":"Kanıt olarak sonucuyla birlikte gerçek bir an verdim.","fa":"یک موقعیت واقعی را همراه با نتیجه‌اش به‌عنوان شاهد گفتم."},{"en":"My weakness was real, and not the main skill of the job.","tr":"Zayıf yönüm gerçekti ve işin ana becerisi değildi.","fa":"نقطه‌ی ضعفم واقعی بود و مهارت اصلیِ آن کار نبود."},{"en":"I said what I am doing about it now.","tr":"Şu anda bunun için ne yaptığımı söyledim.","fa":"گفتم الان برایش چه کار می‌کنم."}],"model":"I'm good at solving problems for unhappy guests. For example, last summer a group's booking failed, and I found them rooms within an hour. They booked with us again this year. My weakness is speaking in big meetings. I used to stay quiet. What I'm doing about it is preparing one point before each meeting and saying it early."},"writing":{"id":"c-int-4-w","course":"interview","unit":"int-4","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":"int-final-2","model":"My main strength is planning. I am good at organising big events on small budgets. For example, last year I organised a conference for 300 people, and we finished 10% under budget. You need someone to run your training events, so this skill fits the role. My biggest weakness is saying no. I used to accept every task and then work late. What I'm doing about it is checking my calendar first and agreeing priorities with my manager.","frame":"My main strength is ___. I am good at ___. For example, last ___. You need ___, so ___. My biggest weakness is ___. I used to ___. What I'm doing about it is ___.","words":[{"word":"good at"},{"word":"For example"},{"word":"used to"}],"minWords":70,"minSentences":5,"title":{"en":"Your strength and weakness answers","tr":"Güçlü ve zayıf yön cevapların","fa":"جواب‌های تو درباره‌ی نقطه‌ی قوت و ضعف"},"prompt":{"en":"Write your answers to 'What are your strengths?' and 'What is your biggest weakness?' for a job you want (70-100 words in total): one strength with proof, one real weakness, and what you are doing about it. No ad yet? Use this one: Customer Support Specialist at an online travel company (two or more years with customers, good written English, weekend shifts; it now sells trips in six new countries). No job yet? Use your studies, a part-time job or volunteer work.","tr":"İstediğin bir iş için 'What are your strengths?' ve 'What is your biggest weakness?' sorularına cevaplarını yaz (toplam 70-100 kelime): kanıtıyla bir güçlü yön, gerçek bir zayıf yön ve bunun için ne yaptığın. Henüz ilanın yok mu? Bunu kullan: Çevrimiçi bir seyahat şirketinde Customer Support Specialist (müşterilerle en az iki yıl deneyim, iyi yazılı İngilizce, hafta sonu vardiyaları; şirket artık altı yeni ülkede seyahat satıyor). Henüz işin yok mu? Okulunu, yarı zamanlı bir işini ya da gönüllü çalışmanı kullan.","fa":"برای کاری که می‌خواهی، جواب‌هایت را به «What are your strengths?‎» و «What is your biggest weakness?‎» بنویس (روی هم ۷۰ تا ۱۰۰ کلمه): یک نقطه‌ی قوت با شاهد، یک ضعف واقعی و کاری که برایش می‌کنی. هنوز آگهی نداری؟ از این استفاده کن: Customer Support Specialist در یک شرکت سفر اینترنتی (دست‌کم دو سال کار با مشتری، انگلیسی نوشتاری خوب، شیفت آخر هفته؛ این شرکت حالا در شش کشور تازه سفر می‌فروشد). هنوز کار نکرده‌ای؟ از تحصیل، کار پاره‌وقت یا کار داوطلبانه‌ات استفاده کن."},"rubric":["Task done: one strength with proof, one real weakness, what you are doing about it","Organised: strength, proof, weakness, fix, in that order","Language: preposition + -ing (good at planning); past simple for the example","Tone: honest and calm, no clichés like 'I'm a perfectionist'"],"rubricI18n":{"tr":["Görev: kanıtıyla bir güçlü yön, gerçek bir zayıf yön, bunun için ne yaptığın","Düzen: güçlü yön, kanıt, zayıf yön, çözüm; bu sırayla","Dil: edat + -ing (good at planning); örnek için past simple","Üslup: dürüst ve sakin; 'I'm a perfectionist' gibi klişeler yok"],"fa":["کامل بودن کار: یک نقطه‌ی قوت با شاهد، یک ضعف واقعی، کاری که برایش می‌کنی","نظم: قوت، شاهد، ضعف، راه‌حل؛ به همین ترتیب","زبان: فعل با ing بعد از حرف اضافه (good at planning)؛ گذشته‌ی ساده برای مثال","لحن: صادق و آرام، بدون کلیشه‌هایی مثل «I'm a perfectionist»"]}},"exit":{"id":"c-int-4-x","course":"interview","unit":"int-4","type":"exit","items":[{"from":"int-4","kind":"blank","prompt":"Our team leader is very good at ___ problems before they get big.","options":["spot","spotting","to spot"],"correct":1,"point":2},{"from":"int-4","kind":"blank","prompt":"I never send a report without ___ the numbers twice.","options":["check","checked","checking"],"correct":2,"point":2},{"from":"int-4","kind":"mcq","prompt":"Which is the best answer to \"What is your biggest weakness?\"","options":["I don't have any weaknesses, because I always check my work very carefully.","I used to avoid hard phone calls, so now I make them first thing in the morning.","I'm a perfectionist, so I sometimes work too hard and care too much."],"correct":1,"point":1},{"from":"int-3","kind":"mcq","prompt":"Which \"Why us?\" answer fits only one company?","options":["I read that you opened a clinic in Konya. I've run booking at a clinic, so I could help.","Your company is famous and successful, with an excellent name in this industry.","I have always wanted to work for a big company with good people and good values."],"correct":0},{"from":"int-2","kind":"mcq","prompt":"A recruiter calls while you are on a noisy street. What do you say?","options":["I'm at work now. Can I call you back at six?","Yes, no problem. Please go on, I can nearly hear you.","Sorry, I can't talk. Please send me an email sometime."],"correct":0},{"from":"int-1","kind":"mcq","prompt":"Which sentence is correct?","options":["I have joined the company in 2021.","I join the company since 2021.","I joined the company in 2021."],"correct":2}]},"explain":{"id":"c-int-4-e","course":"interview","unit":"int-4","type":"explain","level":"B1","title":{"en":"Strengths and weaknesses","tr":"Güçlü ve zayıf yönler","fa":"نقاط قوت و ضعف"},"objective":{"en":"After this lesson, you can prove a strength and talk honestly about a real weakness.","tr":"Bu dersin sonunda bir güçlü yönünü kanıtlayabilecek ve gerçek bir zayıf yönünden dürüstçe bahsedebileceksin.","fa":"بعد از این درس می‌توانی یک نقطه‌ی قوتت را ثابت کنی و صادقانه از یک ضعف واقعی‌ات حرف بزنی."},"hook":{"en":"\"Hard-working\" is only a claim: anyone can say it. Interviewers listen for proof. So name one skill the job needs, prove it with a real moment, and show a real weakness with what you are doing about it.","tr":"\"Çalışkan\" yalnızca bir iddiadır; bunu herkes söyleyebilir. Mülakatçılar kanıt duymak ister. Bu yüzden işin istediği bir beceriyi söyle, onu gerçek bir anla kanıtla ve gerçek bir zayıf yönünü, bunun için ne yaptığınla birlikte anlat.","fa":"«سخت‌کوش» فقط یک ادعاست و هر کسی می‌تواند آن را بگوید. مصاحبه‌کننده‌ها می‌خواهند شاهد بشنوند. پس مهارتی را که این کار لازم دارد نام ببر و با یک موقعیت واقعی ثابتش کن. از یک ضعف واقعی‌ات هم حرف بزن و بگو برای بهتر شدنش چه می‌کنی."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"Claim, proof, link","tr":"İddia, kanıt, bağlantı","fa":"ادعا، شاهد، ربط"},"steps":[{"en":"Choose a strength the ad asks for, and name a skill. Anyone can use an adjective.","tr":"İlanın istediği bir güçlü yön seç ve beceri olarak söyle. Sıfatı herkes kullanabilir.","fa":"نقطه‌ی قوتی را انتخاب کن که آگهی می‌خواهد و آن را به شکل یک مهارت بگو، چون صفت را هر کسی می‌تواند به کار ببرد.","ex":"Not \"hard-working\" but \"good at planning events\""},{"en":"Prove it with one real moment and a result. People remember moments, not adjectives.","tr":"Gerçek bir an ve sonuçla kanıtla. İnsanlar sıfatları değil, anları hatırlar.","fa":"با یک موقعیت واقعی و یک نتیجه ثابتش کن، چون موقعیت در ذهن آدم‌ها می‌ماند، نه صفت.","ex":"Last year I ran a conference for 300 people, 10% under budget."},{"en":"Link it to this job in one sentence, so they don't have to guess why it matters.","tr":"Tek cümleyle bu işe bağla; böylece neden önemli olduğunu tahmin etmek zorunda kalmazlar.","fa":"در یک جمله آن را به همین کار ربط بده تا مجبور نباشند حدس بزنند چرا مهم است.","ex":"You run training days, so this skill fits."},{"en":"For a weakness, choose something real but not central, and say how you are improving.","tr":"Zayıf yön olarak gerçek ama işin merkezinde olmayan bir şey seç ve nasıl geliştiğini söyle.","fa":"برای نقطه‌ی ضعف چیزی واقعی انتخاب کن که مهارت اصلی کار نباشد و بگو چطور داری بهترش می‌کنی.","ex":"I used to avoid meetings. Now I prepare one point each time."}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Good at planning: -ing after a preposition","tr":"Good at planning: edattan sonra -ing","fa":"فعل با ing بعد از حرف اضافه (good at planning)"},"steps":[{"en":"A preposition needs a noun after it, so the verb takes -ing.","tr":"Edattan sonra isim gelir; bu yüzden fiil -ing alır.","fa":"بعد از حرف اضافه باید اسم بیاید؛ برای همین فعل ‎-ing می‌گیرد.","ex":"I'm good at planning projects."},{"en":"Common pairs: good at, responsible for, interested in.","tr":"Sık kullanılanlar: good at, responsible for, interested in.","fa":"جفت‌های رایج: good at، responsible for، interested in.","ex":"I'm interested in learning new systems."},{"en":"before, after and without are prepositions too, so they also take -ing.","tr":"before, after ve without da edattır; bu yüzden onlardan sonra da -ing gelir.","fa":"before، after و without هم حرف اضافه‌اند؛ پس بعد از آن‌ها هم ‎-ing می‌آید.","ex":"I never send a report without checking it."}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["good at + -ing","I'm good at planning projects."],["responsible for + -ing","I'm responsible for training new staff."],["interested in + -ing","I'm interested in learning new software."],["before / after / without + -ing","I never send a report without checking it."]]},"tip":{"en":"Turkish adds a case ending to the verb ('planlamakta iyiyim') and Persian uses a noun ('در برنامه‌ریزی خوبم'), so learners reach for the base verb: 'good at plan'. English needs -ing.","tr":"Türkçede fiile bir ek gelir ('planlamakta iyiyim'). İngilizcede edattan sonra fiil -ing alır: good at planning.","fa":"در فارسی بعد از حرف اضافه اسم یا مصدر می‌آید («در برنامه‌ریزی خوبم»). در انگلیسی بعد از حرف اضافه فعل ‎-ing می‌گیرد: good at planning."},"wrong":"I'm good at to explain numbers.","right":"I'm good at explaining numbers."},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Why they ask about weaknesses","tr":"Zayıf yönleri neden soruyorlar","fa":"چرا درباره‌ی ضعف می‌پرسند"},"body":{"en":"They want to see that you know yourself and can improve. \"I'm a perfectionist\" tells them neither. Choose something small and true. Never choose the main skill of the job, or they will doubt you can do it.","tr":"Kendini tanıdığını ve gelişebildiğini görmek isterler. \"I'm a perfectionist\" bunların hiçbirini göstermez. Küçük ve gerçek bir şey seç. İşin ana becerisini asla seçme, yoksa işi yapabileceğinden şüphe ederler.","fa":"می‌خواهند ببینند خودت را می‌شناسی و می‌توانی بهتر شوی. «I'm a perfectionist» هیچ‌کدام را نشان نمی‌دهد. چیزی کوچک و واقعی انتخاب کن. هیچ‌وقت مهارت اصلیِ آن کار را نگو، وگرنه شک می‌کنند که از پس کار بربیایی."},"phrases":[{"phrase":"I'm good at + -ing","meaning":{"en":"Names a skill, not an adjective.","tr":"Bir sıfat değil, bir beceri söyler.","fa":"یک مهارت را می‌گوید، نه یک صفت."}},{"phrase":"For example, last...","meaning":{"en":"Starts your proof.","tr":"Kanıtını sunmaya başlar.","fa":"شاهدت را شروع می‌کند."}},{"phrase":"What I'm doing about it is...","meaning":{"en":"Turns a weakness into a plan.","tr":"Zayıf yönü bir plana dönüştürür.","fa":"نقطه‌ی ضعف را به یک برنامه تبدیل می‌کند."}},{"phrase":"strength","meaning":{"en":"Something you are especially good at.","tr":"güçlü yön.","fa":"نقطه‌ی قوت"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Turn a claim into proof","tr":"İddiayı kanıta çevir","fa":"ادعا را به شاهد تبدیل کن"},"item":"Weak: I'm hard-working, honest and a real team player. Your facts: last year you ran a conference for 300 people, 10% under budget; this company runs training days.","answer":"I'm good at planning. Last year I ran a conference for 300 people and finished 10% under budget. You run training days, so this skill fits.","walk":[{"en":"Choose one word from the list, and turn it into a skill they can check.","tr":"Listeden bir kelime seç ve onu kontrol edebilecekleri bir beceriye çevir.","fa":"یک کلمه از فهرست انتخاب کن و آن را به مهارتی تبدیل کن که بشود بررسی‌اش کرد."},{"en":"Add one moment with a number, so they can see the skill.","tr":"İçinde sayı olan bir an ekle; böylece beceriyi görebilirler.","fa":"یک موقعیت با عدد اضافه کن تا مهارت را ببینند."},{"en":"End with why it matters for this job.","tr":"Bu iş için neden önemli olduğuyla bitir.","fa":"در آخر بگو چرا این مهارت برای همین کار مهم است."}]},"quick":{"prompt":"I'm really good at ___ difficult numbers simply.","options":["explaining","explain","to explain"],"correct":0,"why":{"en":"explaining: after a preposition like at, the verb takes -ing.","tr":"explaining: at gibi bir edattan sonra fiil -ing alır.","fa":"جواب explaining است، چون بعد از حرف اضافه‌ای مثل at، فعل با ing می‌آید."}},"remember":{"en":"An adjective is a claim. A moment with a number is proof. You can now prove a strength and talk honestly about a weakness. Next, you write both answers for a job you want.","tr":"Sıfat bir iddiadır. İçinde sayı olan bir an ise kanıttır. Artık bir güçlü yönünü kanıtlayabilir ve zayıf bir yönünden dürüstçe bahsedebilirsin. Sırada istediğin bir iş için iki cevabı da yazmak var.","fa":"صفت ادعاست. موقعیتی که عدد دارد شاهد است. حالا می‌توانی یک نقطه‌ی قوتت را ثابت کنی و صادقانه از یک ضعفت حرف بزنی. در ادامه هر دو جواب را برای کاری که می‌خواهی می‌نویسی."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Changing a habit: used to, be used to, get used to","tr":"Bir alışkanlığı değiştirmek: used to, be used to, get used to","fa":"عوض کردن یک عادت: used to، be used to، get used to"},"steps":[{"en":"used to + verb: a past habit that stopped.","tr":"used to + fiil: bitmiş geçmiş bir alışkanlık.","fa":"با used to و فعل ساده از عادتی می‌گویی که در گذشته داشتی و تمام شده است.","ex":"I used to say yes to every task."},{"en":"be used to + -ing: normal for me now.","tr":"be used to + -ing: artık benim için normal.","fa":"با be used to و فعل با ing می‌گویی چیزی حالا برایت عادی است.","ex":"I'm used to working nights."},{"en":"get used to + -ing: becoming normal.","tr":"get used to + -ing: normal hâle geliyor.","fa":"با get used to و فعل با ing می‌گویی چیزی دارد برایت عادی می‌شود.","ex":"I'm getting used to saying no politely."}],"table":{"headers":{"en":["Form","Example"],"tr":["Yapı","Örnek"],"fa":["ساختار","مثال"]},"rows":[["used to + verb: a past habit, stopped","I used to say yes to every task."],["be used to + -ing: normal for me now","I'm used to working nights."],["get used to + -ing: becoming normal","I'm getting used to saying no politely."]]},"body":{"en":"B2: in your weakness answer, show the change with used to, or with be / get used to + -ing.","tr":"B2: zayıf yön cevabında değişimi used to ile ya da be / get used to + -ing ile göster.","fa":"در مسیر B2: در جواب نقطه‌ی ضعفت، تغییر را با used to نشان بده، یا با be used to و get used to و فعل با ing."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
